test_that("R3 likelihood-geometry contract is complete", { root <- normalizePath(testthat::test_path("..", "..")); old <- setwd(root); on.exit(setwd(old), add = TRUE); out <- system2("Rscript", c("tools/verify-ou-v1-r3.R", "--contract"), stdout = TRUE, stderr = TRUE); expect_null(attr(out, "status"), info = paste(out, collapse = "\n")); expect_match(paste(out, collapse = "\n"), "OU_V1_R3_CONTRACT_PASS") })
